import { createInterface } from 'node:readline/promises';
import { spawnResolved } from './command.mjs';
import { existsSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { resolveIdentifier } from './instance.mjs';
import { resolveDevServerPorts } from './ports.mjs';
import { renderAll } from './render.mjs';
import { formatReport, run, runChecks } from './preflight.mjs';
import { attachInstance, detachInstance, ensureProxy } from './proxy.mjs';
import { finishDevServers, selectDevServers, startDevServers } from './devservers.mjs';
import { postgresHint, urlTable } from './report.mjs';
import {
  compose,
  envFileFor,
  postgresHostPort,
  readProxyPort,
  realmHashMarkerFor,
  runInherited,
  seededMarkerFor,
  stateDirFor,
  unhealthyServices,
} from './compose.mjs';
import {
  compareRealmHash,
  hashRealm,
  readStoredRealmHash,
  realmDriftMessage,
  writeRealmHash,
} from './realm-drift.mjs';
import { runEntryPoint } from './entrypoint.mjs';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

export function parseArgs(argv) {
  const options = { fresh: false, detach: false, apps: null, seed: true, limesurvey: false };
  for (const arg of argv) {
    if (arg === '--fresh') {
      options.fresh = true;
    } else if (arg === '--detach') {
      options.detach = true;
    } else if (arg === '--no-seed') {
      options.seed = false;
    } else if (arg === '--with-limesurvey') {
      options.limesurvey = true;
    } else if (arg.startsWith('--apps=')) {
      options.apps = arg.slice('--apps='.length);
    } else {
      throw new Error(
        `Unknown option "${arg}". Valid: --fresh, --detach, --no-seed, --apps=<names>, --with-limesurvey.`,
      );
    }
  }
  return options;
}

// `--profile limesurvey` has to sit before the subcommand, exactly like the `--profile seed` call
// below it already does — both are `docker compose` global flags, not arguments to `up` itself.
export function seedArgs() {
  return [
    '--profile',
    'seed',
    'up',
    '--force-recreate',
    '--exit-code-from',
    'sample-data-loader',
    'sample-data-loader',
  ];
}

export function composeCreateArgs(options) {
  // `create` builds the image and creates the network and containers WITHOUT starting them. The
  // network has to exist before the proxy can be attached to it, and nothing may start before that
  // attachment: the backend reaches Keycloak under the instance's public name, which only resolves
  // inside the network once the proxy answers to it there. Starting first deadlocks — the backend

  // inside the network once the proxy answers to it there. Starting first deadlocks — the backend
  // crash-loops waiting for a proxy that `--wait` is blocking the attachment of.
  const args = ['create', '--build'];
  if (options.limesurvey) {
    return ['--profile', 'limesurvey', ...args];
  } else {
    return args;
  }
}

export function composeUpArgs(options) {
  const upArgs = ['up', '-d', '--wait'];
  if (options.limesurvey) {
    return ['--profile', 'limesurvey', ...upArgs];
  } else {
    return upArgs;
  }
}

/**
 * A fresh run starts with neither the app's sample data nor Keycloak's realm actually imported —
 * `--fresh` wipes the volume both live in (see `startAndWait`'s and the realm-drift check's own
 * comments), so any marker recorded before the wipe describes a database that no longer exists.
 * Pulled out on its own so "does `--fresh` clear both markers" is a plain, disk-backed unit test
 * instead of only reachable through `main()`'s full docker-and-network sequence.
 */
export function clearFreshState({ seededMarker, realmHashMarker }) {
  rmSync(seededMarker, { force: true });
  rmSync(realmHashMarker, { force: true });
}

/**
 * Of the instances `ensureProxy` had to reattach after force-recreating the shared proxy for a
 * port change, the ones whose *own* rendered artifacts still say the old port — their containers
 * keep working (the Keycloak issuer only depends on the public hostname, not the port), but their
 * browsers now point at a proxy that no longer listens where they expect, and nothing about a
 * successful-looking `just up` would otherwise say so.
 */
export function staleReattachedInstances(reattached, proxyPort, readProxyPortFor = readProxyPort) {
  return reattached.filter((instance) => {
    try {
      return readProxyPortFor(instance) !== proxyPort;
    } catch {
      // No readable rendered port for that instance — nothing to compare, so don't warn about it.
      return false;
    }
  });
}

export function staleReattachedWarning(instances) {
  if (instances.length === 0) {
    return null;
  }
  const plural = instances.length > 1;
  return (
    `\nWARNING: the shared proxy was just recreated on a new port, but ${instances.join(', ')} ` +
    `${plural ? 'were' : 'was'} rendered for a different one. ${plural ? 'Their' : 'Its'} ` +
    `container${plural ? 's' : ''} still work${plural ? '' : 's'} fine, but ${plural ? 'their' : 'its'} ` +
    `browser${plural ? 's' : ''} can no longer reach ${plural ? 'them' : 'it'} through the proxy. ` +
    `Re-run \`just up\` in ${plural ? 'those worktrees' : 'that worktree'} to fix ${plural ? 'them' : 'it'}.`
  );
}

/**
 * `up --wait` fails with nothing but an exit code, and Docker's own line is only "dependency failed
 * to start". Naming the container and where to look turns a dead end into a next step — this exact
 * message cost a user two debugging rounds.
 */
async function startAndWait(instance, options) {
  try {
    await compose(instance, composeUpArgs(options));
  } catch (error) {
    const stuck = await unhealthyServices(instance, run);
    if (stuck.length > 0) {
      const named = stuck.map(({ service, status }) => `  ${service} (${status})`).join('\n');
      throw new Error(
        `${error.message}\n\nNot healthy yet:\n${named}\n\n` +
          `Look at what it is doing: just logs ${stuck[0].service}\n` +
          `A cold start can be slow; re-running just up picks up where this left off.`,
      );
    } else {
      throw error;
    }
  }
}

export async function main(argv) {
  const options = parseArgs(argv);
  const proxyPort = Number(process.env.URBO_PROXY_PORT ?? 80);

  const checks = await runChecks({ proxyPort, env: process.env, exec: run });
