/**
 * One instance per worktree. The identifier is the worktree directory name by default, asked for
 * once and then remembered, so switching branches never swaps the database out from under the
 * same workspace.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, join } from 'node:path';

const STORE_FILE = '.urbo-instance';
const MAX_LENGTH = 40;

export function normaliseIdentifier(raw) {
  const identifier = String(raw ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, MAX_LENGTH)
    .replace(/-+$/, '');

  if (identifier === '') {
    throw new Error(
      `"${raw}" contains no characters usable in an instance identifier (need at least one of a-z or 0-9).`,
    );
  } else {
    return identifier;
  }
}

export function defaultIdentifier(repoRoot) {
  return normaliseIdentifier(basename(repoRoot));
}

export function readStoredIdentifier(repoRoot) {
  const path = join(repoRoot, STORE_FILE);
  if (existsSync(path)) {
    const stored = readFileSync(path, 'utf8').trim();
    if (stored === '') {
      return null;
    } else {
      return stored;
    }
  } else {
    return null;
  }
}

export function storeIdentifier(repoRoot, identifier) {
  mkdirSync(repoRoot, { recursive: true });
  writeFileSync(join(repoRoot, STORE_FILE), `${identifier}\n`);
}

/**
 * What every recipe except `just up` uses. `up` may prompt and create an instance; the others must
 * only ever address one that already exists — and must normalise exactly as `up` did, or an
 * un-normalised URBO_INSTANCE would point them at a different, malformed stack.
 */
export function currentInstance({ repoRoot, envValue }) {
  const raw = envValue || readStoredIdentifier(repoRoot);
  if (raw) {
    return normaliseIdentifier(raw);
  } else {
    throw new Error('No instance for this worktree yet. Run `just up` first.');
  }
}

export async function resolveIdentifier({ repoRoot, envValue, prompt }) {
  if (envValue) {
    // Deliberately not persisted: an override is for one run, not a new default.
    return normaliseIdentifier(envValue);
  } else {
    const stored = readStoredIdentifier(repoRoot);
    if (stored) {
      return normaliseIdentifier(stored);
    } else {
      const fallback = defaultIdentifier(repoRoot);
      const answer = await prompt('Instance identifier', fallback);
      const identifier = normaliseIdentifier(answer.trim() === '' ? fallback : answer);
      storeIdentifier(repoRoot, identifier);
      return identifier;
    }
  }
}

