/**
 * The single home for talking to `docker compose` about an instance's stack: the compose file
 * path, its `.urbo/<instance>` state directory (and the env file / seeded marker inside it), and
 * an inherited-stdio runner. `up.mjs` and `cli.mjs` used to each declare their own `COMPOSE_FILE`
 * and their own inherited-stdio runner (the latter in `cli.mjs` with no `child.on('error')`
 * handler, so a missing `docker` binary left its promise pending forever); `up.mjs`, `serve.mjs`,
 * `native.mjs` and `proxy.mjs` each hand-built the `.urbo/<instance>` path a second time; and
 * `up.mjs`'s `postgresPort` / `backend-local.mjs`'s `postgresHostPort` were the same function
 * twice, on top of `runInherited` being written out a third and fourth time in `native.mjs` and
 * `backend-local.mjs` with two more, slightly different parameter shapes.
 */

import { spawnResolved } from './command.mjs';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

export const COMPOSE_FILE = join(REPO_ROOT, 'backend/docker/docker-compose.yml');

/**
 * `.urbo/<instance>`, the one directory every rendered artifact (env file, nginx.conf, imports,
 * ports.json, the seeded marker) lives under. `repoRoot` defaults to this module's own repo root
 * — every real entry point wants that — but stays overridable so tests (e.g. `render.mjs`'s
 * `renderAll`) can point it at a scratch directory instead of touching the real repo.
 */
export function stateDirFor(instance, repoRoot = REPO_ROOT) {
  return join(repoRoot, '.urbo', instance);
}

export function envFileFor(instance) {
  return join(stateDirFor(instance), 'env');
}

/**
 * Written only once the seeder has actually exited 0 (see `up.mjs`'s seeding block) — its absence
 * always means "never successfully seeded". Both `up.mjs` (writes it) and `cli.mjs`'s `reset`
 * (must remove it, so a wiped database isn't reported as "reusing the existing database" on the
 * next `just up`) need this exact path.
 */
export function seededMarkerFor(instance) {
  return join(stateDirFor(instance), 'seeded');
}

/**
 * Sits beside `seededMarkerFor` for the same reason: both track state that lives inside the one
 * `urbo-cms-data` Postgres volume (the `urbo` and `keycloak` databases are two databases on the
 * same Postgres server, see `docker-compose.yml`'s `POSTGRES_DB2`). Holds the sha256 of the realm
 * `up.mjs` last rendered *and confirmed Keycloak actually imported* — see `realm-drift.mjs` for why
 * a changed realm otherwise goes silently unimported, and `up.mjs`'s `needsSeed` call site for
 * exactly when that confirmation happens. `cli.mjs`'s `reset` must remove this one too, or a wiped
 * `keycloak` database would be checked against a hash from before the wipe.
 */
export function realmHashMarkerFor(instance) {
  return join(stateDirFor(instance), 'realm-hash');
}

/** The `compose --env-file … -f … <args>` prefix every caller needs, assembled in one place. */
export function composeArgs(instance, args) {
  return ['compose', '--env-file', envFileFor(instance), '-f', COMPOSE_FILE, ...args];
}

/**
 * Reads back the proxy port `just up` last rendered this instance's artifacts for, straight out of
 * its rendered env file (`render.mjs`'s `composeEnv` writes `URBO_PROXY_PORT` there). `just urls`,
 * `just open` and `just serve` run in whatever shell a developer happens to have open —
 * `URBO_PROXY_PORT` may well not be exported there — so they must recover the port from what was
 * actually rendered instead of re-deriving or defaulting it themselves.
 */
export function readProxyPort(instance) {
  const path = envFileFor(instance);
  if (!existsSync(path)) {
    throw new Error(`No rendered environment for "${instance}" at ${path}. Run \`just up\` first.`);
  }
  const match = readFileSync(path, 'utf8').match(/^URBO_PROXY_PORT=(\d+)$/m);
  if (!match) {
    throw new Error(`"${path}" has no URBO_PROXY_PORT recorded — re-render with \`just up\`.`);
  }
  return Number(match[1]);

