/**
 * The three Angular dev servers run on the host, on ports the orchestrator allocated, and are
 * fronted by the proxy under their public hostnames.
 *
 * HMR needs no proxy configuration: Vite's client connects to `location.hostname` on the dev
 * server's own port, and `*.localhost` resolves to 127.0.0.1 — which is one of the addresses the
 * dev server listens on. The websocket therefore goes straight past the proxy. All the dev server
 * needs is `--allowedHosts`, so it accepts the proxied `Host` header on the HTTP requests.
 *
 * The bind address has to be `0.0.0.0`, not `127.0.0.1`: the proxy reaches these servers from
 * inside a container, through `host.docker.internal`. On Docker Desktop that name is routed by the
 * VM and does reach the host's loopback, but on native Linux it is a plain `host-gateway` alias for
 * the bridge address (172.17.0.1), which a loopback-only listener refuses — every app/cms/boards
 * request then 502s while the dev server itself looks perfectly healthy.
 */

import { join } from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';
import { DEV_SERVERS, publicHostname } from './services.mjs';

// Grace period between asking a dev server to stop (SIGTERM) and giving up on it and forcing the
// issue (SIGKILL). Without an upper bound, a dev server that ignores SIGTERM would wedge stop()
// forever; without waiting at all, `just up`'s Ctrl-C path could return before the port is
// actually free, and the next `just up` would allocate a different one - or fail to bind it. 5s
// is enough for Vite/Nx to unwind their own child processes on a normal machine, but short enough
// that Ctrl-C still feels responsive.
const STOP_GRACE_MS = 5000;

export function selectDevServers(selection) {
  if (selection === null || selection.trim() === '') {
    return [...DEV_SERVERS];
  } else {
    const wanted = new Set(selection.split(',').map((name) => name.trim()));
    const valid = new Set(DEV_SERVERS.map((entry) => entry.name));
    for (const name of wanted) {
      if (!valid.has(name)) {
        throw new Error(`Unknown app "${name}". Valid names: ${[...valid].join(', ')}.`);
      }
    }
    return DEV_SERVERS.filter((entry) => wanted.has(entry.name));
  }
}

export function serveArgs({ project, port, hostname }) {
  return [
    'nx',
    'serve',
    project,
    '--configuration=instance',
    `--port=${port}`,
    '--host=0.0.0.0',
    `--allowedHosts=${hostname}`,
  ];
}

export async function startDevServers({
  repoRoot,
  instance,
  ports,
  selection,
  spawnProcess,
  stopGraceMs = STOP_GRACE_MS,
}) {
  const state = { stopRequested: false };
  const { promise: crashed, reportCrash } = crashSignal();

  const children = selectDevServers(selection).map(({ name, project }) =>
    launch({ repoRoot, instance, name, project, ports, spawnProcess, state, reportCrash }),
  );

  return {
    crashed,
    stop: async () => {
      state.stopRequested = true;
      await Promise.all(children.map((child) => stopChild(child, stopGraceMs)));
    },
  };
}

