    console.error(
      `\n[${crash.name}] crashed unexpectedly (code=${crash.code ?? 'null'}, signal=${crash.signal ?? 'null'}). ` +
        'Stopping the rest and exiting with an error.',
    );
    return 1;
  } else {
    return 0;
  }
}

function defaultWaitForSignal() {
  return new Promise((resolve) => {
    process.on('SIGINT', resolve);
    process.on('SIGTERM', resolve);
